// Needs-a-look strip (story 5.12, PD-7): at most three facilities from report_flags, those flagged on
// two or more reports first, then most patients. Chips open the tab with the same location and month.
const root = context.element.querySelector('.rpt-nal-root');
if (!root) { return; }
const { esc, fmt, num } = rpt;
const head = '<div class="rpt-nal-head"><span class="rpt-nal-title">Needs a look first</span>'
  + '<span class="rpt-demo">Demo data. Facility names and numbers are made up.</span></div>';
if (!rpt.allowed()) { root.innerHTML = head + rpt.banner(); return; }
const tabOrder = rpt.TABS.map((t) => t.report);
const by = {};
rpt.rows('A').filter((f) => tabOrder.includes(f.report)).forEach((f) => {
  const k = String(f.org_unit_id);
  (by[k] = by[k] || { name: String(f.org_unit_name || ''), patients: num(f.patients_n) || 0, items: [] }).items.push(f);
});
// Ties on patients go to the facility with more flags, then by name.
const list = Object.values(by).sort((a, b) => (b.items.length >= 2) - (a.items.length >= 2) || b.patients - a.patients
  || b.items.length - a.items.length || a.name.localeCompare(b.name)).slice(0, 3);
const chip = (f) => '<a class="rpt-chip" href="' + esc(rpt.link(f.report)) + '" title="' + esc(f.flag_reason) + '">' + esc(rpt.tab(f.report).title) + '</a>';
root.innerHTML = head + (list.length
  ? '<ul class="rpt-nal">' + list.map((f) => '<li><span class="rpt-nal-name">' + esc(f.name) + '</span>'
    + '<span class="rpt-nal-n">' + fmt(f.patients) + ' patients</span>'
    + '<div class="rpt-chips" aria-label="Reports that flag ' + esc(f.name) + '">'
    + f.items.slice().sort((a, b) => tabOrder.indexOf(a.report) - tabOrder.indexOf(b.report)).map(chip).join('') + '</div></li>').join('') + '</ul>'
  : '<div class="rpt-muted">' + esc(rpt.NO_FLAGS) + '</div>');
